#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""PASQAL L4 exact-root direct ordering theorem — standalone Colab v1.1.

Run this in the same Colab runtime after the successful Krawczyk v1.2 audit.
It reads the Krawczyk certificate and the earlier frozen formal order-30
certificate, then propagates every certified phase box through direct
six-point finite-error Arb calculations and a secondary order-30 jet audit.

Preflight:
    %run /content/pasqal_L4_exact_root_ordering_standalone_colab.py --preflight-only

Full audit:
    %run /content/pasqal_L4_exact_root_ordering_standalone_colab.py
"""
from __future__ import annotations
import base64
import gzip
import sys
import types

_EMBEDDED = {'_exact_root_main': '',
 'pasqal_L4_arb_formal_audit': '',
 'pasqal_two_atom_matched_fibre_test': '',
 'pasqal_two_atom_q2_prospective_ranking': ''} 


def _source(key: str) -> bytes:
    return gzip.decompress(base64.b64decode(_EMBEDDED[key]))


def _install(name: str) -> None:
    module = types.ModuleType(name)
    module.__file__ = f"<embedded:{name}>"
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(_source(name), module.__file__, "exec"), module.__dict__)


def main() -> None:
    print(
        "[start] L4 exact-root direct ordering theorem + order-30 mechanism "
        "audit v1.1; "
        "expected runtime several minutes after preflight...",
        flush=True,
    )
    _install("pasqal_two_atom_matched_fibre_test")
    _install("pasqal_two_atom_q2_prospective_ranking")
    _install("pasqal_L4_arb_formal_audit")
    runtime_file = globals().get("__file__", "<colab-notebook-cell>")
    namespace = {
        "__name__": "__main__",
        "__file__": runtime_file,
        "__package__": None,
    }
    exec(
        compile(
            _source("_exact_root_main"),
            "<embedded:exact_root_ordering_audit>",
            "exec",
        ),
        namespace,
    )


if __name__ == "__main__":
    main()
